INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Office 29', 'In Office 29, a seemingly normal workday turns into a nightmarish journey through a haunted office. You wake up at night, alone, and must gather your belongings while navigating terrifying anomalies that distort reality. As you explore, strange events unfold—lights flicker, shadows move, and eerie figures lurk outside the window. Each anomaly hides secrets, pushing you deeper into the unknown.' FROM games WHERE igdb_id = 325743 ON CONFLICT (game_id, language_code) DO NOTHING;
