INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('variable-geo-vs-asuka-120-percent', 316595, '2024-08-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8t9d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar34bh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Variable Geo vs. Asuka 120%', 'Variable Geo vs. Asuka 120% is a crossover fighting game with characters from Variable Geo and Asuka 120%. Here everything will be standard as in many fighting games, but with differences. For example, some characters from Asuka 120% received new specials and improved supers that differed from the original. Here you will find a couple of mini-games, several additional modes and the ability to play online multiplayer (Network). Have fun in team mode and tag team mode, compete with each other in local or online, practice in training mode and free match. Whatever you want, there are not many modes, but there are enough of them. It is well suited for both tournaments and online gatherings.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 316595 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
