INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Honor of Nations', 'Honor of Nations delivers unmatched MMORPG experience in mobile platforms. Honor of Nations mobile captures the essence of classic MMORPGs, offering a vast, open world filled with quests, dungeons, and a rich lore. Immerse yourself in epic adventures, all within the convenience of your mobile device. Whether you''re commuting, waiting in line, or just relaxing at home, your journey in Honor of Nations is always just a tap away.' FROM games WHERE igdb_id = 286871 ON CONFLICT (game_id, language_code) DO NOTHING;
