INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wardens of Romance', 'As the only human employee at a supernatural post office, you deal with cursed and bizarre items that would cause a normal human to go mad… But not you. When a mysterious package arrives, three demon brothers insist on joining you on the most important delivery of your life. The path ahead is foggy, but with three handsome companions, there’s nothing to fear… except the fourth demon. Will you rise to the occasion and come out stronger than ever?' FROM games WHERE igdb_id = 322322 ON CONFLICT (game_id, language_code) DO NOTHING;
