INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cryptic Escape', 'Monsters are taking hard earned dwarven treasure, and the dwarves have had enough. You are chosen are their champion, and are sent into the dungeons to recover your treasure, problem is... No one taught you how to fight the monsters, so your best option is to sneak by, and hope they don''t catch you.' FROM games WHERE igdb_id = 289690 ON CONFLICT (game_id, language_code) DO NOTHING;
