INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Frontiers', 'A Gripping 2D Side-Scrolling Strategy Tower Defense Extravaganza. In this forgotten frontier, you become the final line of defense for your city, warding off relentless hordes of monstrous invaders. This is not just a battle for survival; it''s a supreme test of wit and strategy.' FROM games WHERE igdb_id = 304606 ON CONFLICT (game_id, language_code) DO NOTHING;
