INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kafka''s Metamorphosis', 'Kafka''s Metamorphosis'' is an emotional short-form story game based on the life of Czech writer Franz Kafka and his most famous novella, ''The Metamorphosis''. The game is set in the fall of 1912 when Kafka wrote The Metamorphosis. It captures Kafka''s struggle to live as a writer while being pressured to fulfill roles as a young man, employee, and eldest son. The game aims to explore and express why Kafka wrote The Metamorphosis.' FROM games WHERE igdb_id = 328219 ON CONFLICT (game_id, language_code) DO NOTHING;
