INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StoicScape', 'Recruited by a mysterious wanderer named Marcus Aurelius, you will embark upon a series of "Stoic Trials," where you will gather philosophical insights for his unfinished book, "Meditations." Extract resources, defeat enemies, and confront epic bosses to become a master stoic.' FROM games WHERE igdb_id = 289255 ON CONFLICT (game_id, language_code) DO NOTHING;
