INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Edda Physics 1', 'Edda Physics 1 is a VR educational app that turns core physics concepts into hands-on, interactive labs. Six immersive modules—Archimedes’ Principle, Newton’s Laws of Motion, Nuclear Physics, Theory of Relativity, the Coriolis Effect, and Coulomb’s Law—let users manipulate variables and observe real‑time results, bridging theory and practice with scientifically grounded pedagogy. The experience emphasizes interactive learning and clarity, making complex topics accessible and engaging in virtual reality.' FROM games WHERE igdb_id = 389084 ON CONFLICT (game_id, language_code) DO NOTHING;
