INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imobilidade Urbana', 'Imobilidade Urbana is a horror side-scroller developed by the Homeless Workers'' Movement Technology Center based on the issues related to the privatizations of São Paulo''s transport and water systems, where control Glória who was on her way home from nursing work and came across a fault on the last train of the night. She gets stuck on the dark train and can''t get off. The train announcer explains that the passengers must get out as quickly as possible, as their lives are at risk.' FROM games WHERE igdb_id = 283611 ON CONFLICT (game_id, language_code) DO NOTHING;
