INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TDS: Tower Destiny Survive', 'Tower Destiny Survive is a fast-paced tower defense RPG where you build and upgrade a mobile fortress to survive relentless waves of zombies. Collect blocks, strategize your layout, and equip your tower with flamethrowers, guns, and traps as you travel through the post-apocalyptic world. Fight off hordes of the undead, level up your weapons, and keep moving—because once your defenses fall, it''s game over.' FROM games WHERE igdb_id = 353603 ON CONFLICT (game_id, language_code) DO NOTHING;
