INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Purrfect Alchemy', 'Purrfect Alchemy is a "purrfect" blend of twin stick shooter, wave survival, tower defender. Craft defenses at the center cauldron with a variety of ingredients you may find. Upgrade spells, defeat bosses and reach the end with up to 3 other friends in this Co-Op adventure' FROM games WHERE igdb_id = 337808 ON CONFLICT (game_id, language_code) DO NOTHING;
