INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pileup', 'In PILEUP you play as a green square that is trying to rise up by substituting gray squares underneath it. Since reaching the top of the green square will end the game, you must prevent it from rising. Pink rectangles will fall from above and destroy all the blocks in their path, including you. Dodge them to live as long as possible and earn more points.' FROM games WHERE igdb_id = 315381 ON CONFLICT (game_id, language_code) DO NOTHING;
