INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-story-goes-on-chapter-3', 337690, '2024-12-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lre.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw19t.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Story Goes On Chapter 3', 'The party explores the Sunken Citadel, a ruin tied to the chaotic forces they’ve been tracking, braving spectral warriors, a cursed Sea Lord, and a collapsing structure to retrieve a powerful artifact. Their journey leads them to the foreboding Veil of Shadows, where they face shadowy beasts, trials of combat and persuasion, and traverse into the Shadow Realm itself. There, they uncover a shard of primordial light but provoke a mysterious force, setting the stage for a perilous escape and new challenges ahead.' FROM games WHERE igdb_id = 337690 ON CONFLICT (game_id, language_code) DO NOTHING;
