INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-last-of-the-9-lives', 319179, '2024-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8z1m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar362e.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last of the 9 Lives', 'In this fast-paced, infinite jumping adventure, guide your cat as they leap from platform to platform, racing against the rising water that speeds up the longer you survive. Precision and quick reflexes are key as you collect milk and fish for bonus points, all while navigating randomly generated platforms. With its charming pixel art and simple controls, the game offers a challenging yet rewarding experience where every jump counts. A throwback to simpler times. How high can you climb before the water catches up?' FROM games WHERE igdb_id = 319179 ON CONFLICT (game_id, language_code) DO NOTHING;
