INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elemental Cube', '"Elemental Cube" takes you on a challenging and thought-provoking journey through a magical world. This single-player puzzle game consists of 50 unique levels, each requiring players to overcome obstacles with strategy, logic, and creativity. At the heart of the game is a mystical cube, with each face representing one of the four fundamental elements: fire, water, earth, and air.' FROM games WHERE igdb_id = 308317 ON CONFLICT (game_id, language_code) DO NOTHING;
