INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Greengrocer Simulator 2024', 'Can you rebuild a career that has hit rock bottom? Strive to rise from nothing to the top. Arrange your fruits & vegetables however you like. Keep track of price updates. Play the stock market and aim for the top. Meet people and grab a drink. Show the whole world who''s the best.' FROM games WHERE igdb_id = 326419 ON CONFLICT (game_id, language_code) DO NOTHING;
