INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('katagiri-san-is-very-cold--2', 372817, '2024-11-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coanv0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4fii.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Katagiri-san is Very Cold', 'You wake up in a dimly lit room, with your classmate Katagiri-san in front of you. Why are you here? Who could''ve done it? Why is she here? Maybe there is a way to get out of this place... Try to find your way out in this short escape room RPG with hints of horror, comedy, and a bit of spice!' FROM games WHERE igdb_id = 372817 ON CONFLICT (game_id, language_code) DO NOTHING;
