INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Story Goes On Chapter 5', 'The party ventures into the Labyrinth of Echoes, a ruin amplifying their inner emotions, to retrieve a mysterious artifact. After overcoming shadowy clones of themselves, they acquire an orb, unwittingly freeing the Shadow Lord, who vows vengeance. The ensuing battle delays the Shadow Lord''s full return, but the party must now seek guidance from the Seers of Vahlara, as a cloaked figure reveals their journey is far from over.' FROM games WHERE igdb_id = 337693 ON CONFLICT (game_id, language_code) DO NOTHING;
