INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imprimatura', 'Imagine that you are an artist. Imagine that you are in mourning. A painter – your relative, and your former mentor – has died. In their will, they have left you seven paintings of your choosing from their collection. But which seven? What matters to you as both an artist and an inheritor of your mentor’s legacy? And what memories will these paintings stir up?INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 325145 AND c.slug = 'elizabeth-ballou' ON CONFLICT DO NOTHING;
