INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Final Cursed Days', 'My Final Cursed Days is a fantasy mix of dungeon-crawling RPG and time-management life-sim made for the Game Boy! Navigate a strange dungeon in the first-person. Fight monsters, find magic artifacts, make choices, chat with villagers! You only have so much time left after all.' FROM games WHERE igdb_id = 336483 ON CONFLICT (game_id, language_code) DO NOTHING;
