INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ghost-invasion-idle-hunter', 340343, '2024-10-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9oka.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwb3l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost Invasion: Idle Hunter', 'Ghost Invasion: Idle Hunter is a mobile idle RPG where players become ghost hunters, capturing spirits that have invaded the world. Developed by Miniclip, the game blends casual idle gameplay with action and RPG mechanics. Players can upgrade their hunter''s gear, enhance ghost-catching abilities, and unlock new haunted locations. With each level, stronger ghosts and powerful bosses appear, challenging players to improve their strategy and timing. Featuring atmospheric visuals and a spooky soundtrack, the game offers a hauntingly fun experience for fans of idle and casual RPGs.' FROM games WHERE igdb_id = 340343 ON CONFLICT (game_id, language_code) DO NOTHING;
