INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I''m a Gensokyo Observer', 'You worked in a company known for getting rid of anomalies and any paranormal activities. One day, you received a letter from Yukari, asking for your assistance in Gensokyo about paranormal activities which this time, it''s from a different source. You have to take care of the anomalies in Gensokyo and make Gensokyo safe again. Good luck.' FROM games WHERE igdb_id = 324754 ON CONFLICT (game_id, language_code) DO NOTHING;
