INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fight Of Escaper', 'Humanity has lost sight of itself, blinded by the false prosperity of AI development. You, the protagonist, begin to break free from AI control to uncover the truth of this world. Torn between escaping and erasing your memory, you yearn to leave this city of mechas and reach the shores of freedom.' FROM games WHERE igdb_id = 370032 ON CONFLICT (game_id, language_code) DO NOTHING;
