INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mia and Me: Magic Friends', 'Take your unicorn for a ride through enchanting tracks. Discover the Rainbow Island, Crystal Cave, Heart Valley, Blackwood Forest, and many more magical locations. Help Mia, Yuko and Mo protect Centopia - take on exciting quests, search for magical items, and then, with the help of Phuddle, banish Gargona and the other villains! And then there''s the cute little ponycorns you''re sure to fall in love with too!' FROM games WHERE igdb_id = 325398 ON CONFLICT (game_id, language_code) DO NOTHING;
